package in.aicon.pocket;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import org.json.*;
/** Whole invalid candidate ledger is private staging, not visible financial data.
 * A choice creates a permanent tombstone only after the complete ledger validates.
 */
final class RepaymentReviewStore {
 static final class Review {final String key;final long revision;final LedgerIntegrity.RepaymentConflict issue;final Map<String,SyncModel.Record> records;Review(String key,long revision,LedgerIntegrity.RepaymentConflict issue,Map<String,SyncModel.Record> records){this.key=key;this.revision=revision;this.issue=issue;this.records=Collections.unmodifiableMap(records);}}
 private final SQLiteDatabase db;
 RepaymentReviewStore(SQLiteDatabase db,String subject){if(!new java.io.File(db.getPath()).getName().equals(AccountScope.databaseFor(subject)))throw new IllegalArgumentException("Wrong repayment-review account");this.db=db;db.execSQL("CREATE TABLE IF NOT EXISTS repayment_review(singleton INTEGER PRIMARY KEY CHECK(singleton=1),token TEXT NOT NULL,revision INTEGER NOT NULL,records TEXT NOT NULL)");}
 void save(long revision,Map<String,SyncModel.Record> records)throws Exception{if(!db.inTransaction())throw new IllegalStateException("Stage review in a transaction");try{LedgerWire.validate(records);throw new IllegalArgumentException("Candidate does not need repayment review");}catch(LedgerIntegrity.RepaymentConflict expected){}JSONArray json=new JSONArray();for(SyncModel.Record r:records.values())json.put(new JSONObject(SyncJson.record(r)));String body=json.toString();if(body.length()>8*1024*1024||revision<0)throw new IllegalArgumentException("Invalid review size or revision");ContentValues values=new ContentValues();values.put("singleton",1);values.put("token",UUID.randomUUID().toString());values.put("revision",revision);values.put("records",body);if(db.insertWithOnConflict("repayment_review",null,values,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new IllegalStateException("Could not retain repayment review");}
 Review current()throws Exception{try(Cursor c=db.rawQuery("SELECT token,revision,records FROM repayment_review WHERE singleton=1",null)){if(!c.moveToFirst())return null;String key=c.getString(0);Identifiers.uuid(key);JSONArray json=new JSONArray(c.getString(2));Map<String,SyncModel.Record> records=new TreeMap<>();for(int n=0;n<json.length();n++){SyncModel.Record r=SyncJson.parseRecord(json.getJSONObject(n).toString());if(records.put(r.id,r)!=null)throw new IllegalArgumentException("Duplicate candidate");}try{LedgerWire.validate(records);}catch(LedgerIntegrity.RepaymentConflict issue){return new Review(key,c.getLong(1),issue,records);}throw new IllegalStateException("Repayment review changed. Sync again.");}}
 void clear(){if(!db.inTransaction())throw new IllegalStateException("Clear review atomically");db.delete("repayment_review",null,null);}
}
